node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// List tables and columns
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
tables.forEach(t => {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log(t.name + ':', info.map(c => c.name).join(', '));
});
console.log();

// Search for the order
for (const t of tables) {
  try {
    const rows = db.prepare('SELECT * FROM ' + t.name + ' LIMIT 1').all();
    if (rows.length > 0) {
      const vals = JSON.stringify(rows[0]);
      if (vals.includes('ORD') || vals.includes('order') || vals.includes('Aurora') || vals.includes('lamp')) {
        console.log('=== Match in', t.name, '===');
        console.log(JSON.stringify(rows[0], null, 2));
      }
    }
  } catch(e) {}
}

// Direct searches
for (const t of tables) {
  for (const col of db.prepare('PRAGMA table_info(' + t.name + ')').all()) {
    try {
      const q = 'SELECT * FROM ' + t.name + ' WHERE CAST(' + col.name + ' AS TEXT) LIKE \"%ORD-E0E671%\" OR CAST(' + col.name + ' AS TEXT) LIKE \"%Aurora%\"';
      const r = db.prepare(q).all();
      if (r.length > 0) {
        console.log('=== Found in ' + t.name + '.' + col.name + ' ===');
        r.forEach(row => console.log(JSON.stringify(row, null, 2)));
      }
    } catch(e) {}
  }
}
db.close();
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Order details
console.log('=== ORDER ORD-E0E671 ===');
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-E0E671'\").get();
console.log(JSON.stringify(order, null, 2));

// Order items
console.log('\n=== ORDER ITEMS ===');
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-E0E671'\").all();
items.forEach(i => console.log(JSON.stringify(i, null, 2)));

// Aurora product
console.log('\n=== AURORA SMART DESK LAMP PRO (Product) ===');
const product = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Aurora%'\").get();
console.log(JSON.stringify(product, null, 2));

// Warranties for this order
console.log('\n=== WARRANTIES ===');
const warranties = db.prepare(\"SELECT * FROM warranties WHERE order_id = 'ORD-E0E671'\").all();
warranties.forEach(w => console.log(JSON.stringify(w, null, 2)));
if (warranties.length === 0) console.log('(none)');

// Fulfillments
console.log('\n=== FULFILLMENTS ===');
const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'ORD-E0E671'\").all();
fulfillments.forEach(f => console.log(JSON.stringify(f, null, 2)));
if (fulfillments.length === 0) console.log('(none)');

// Payments
console.log('\n=== PAYMENTS ===');
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-E0E671'\").all();
payments.forEach(p => console.log(JSON.stringify(p, null, 2)));
if (payments.length === 0) console.log('(none)');

// Customer
console.log('\n=== CUSTOMER ===');
const cust = db.prepare(\"SELECT * FROM users WHERE user_id = ?\").get(order?.customer_id);
if (cust) {
  const {purchase_history_json, payment_methods_json, saved_passengers_json, ...rest} = cust;
  console.log(JSON.stringify(rest, null, 2));
}

// Variants for Aurora
if (product) {
  console.log('\n=== VARIANTS ===');
  const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = ?\").all(product.product_id);
  variants.forEach(v => console.log(JSON.stringify(v, null, 2)));
  if (variants.length === 0) console.log('(none)');
}

db.close();
"
